const domains={neuro:b('脑疾病 / AD','Brain disease / AD'),immune:b('免疫 / 慢性病','Immune / chronic disease'),cell:b('细胞基础模型','Cell foundation models'),perturb:b('干预响应','Perturbation response'),causal:b('因果 / 实验设计','Causality / experimental design'),spatial:b('空间组织','Spatial tissues'),evaluation:b('评测与可靠性','Evaluation & reliability'),genome:b('基因组 / 变异','Genomics / variants'),protein:b('分子结构','Molecular structure'),drug:b('药物 / 靶点','Drugs / targets'),pathology:b('肿瘤 / 数字病理','Cancer / digital pathology'),agent:b('科研 Agent','Scientific agents'),clinical:b('临床记录','Clinical records')};
const glossary=[
['Single-cell RNA / scRNA-seq','单细胞 RNA 测序','分别读出细胞正在使用哪些基因；不能直接看到所有蛋白或因果关系。','Measures which genes each cell is using; does not directly measure all proteins or causal relationships.'],
['Single-nucleus / snRNA-seq','单核测序','用细胞核而不是完整细胞，常用于冷冻脑组织；与单细胞测量存在系统差异。','Measures nuclei rather than whole cells, often in frozen brain tissue; differs systematically from whole-cell assays.'],
['Perturb-seq','带干预的单细胞测序','先改变基因，再读出表达。通常不能在干预前后测到同一个活细胞。','Change genes, then measure expression. Typically cannot measure the same living cell before and after treatment.'],
['CRISPRi / CRISPRa','基因抑制 / 激活','让基因表达降低或升高；不总是把基因完全删除。','Reduce or increase gene expression; not always complete gene deletion.'],
['GRN','基因调控网络','哪些基因可能调控另一些基因；推断网络里的边不一定已获因果验证。','A map of possible regulation between genes; inferred edges need not be causally validated.'],
['ATAC-seq','染色质开放性','检测 DNA 哪些区域较开放，为调控关系提供线索。','Measures accessible DNA regions, providing clues about regulation.'],
['Hi-C','DNA 三维接触','测量远距离 DNA 区域的空间接近程度；接触不一定发生功能调控。','Measures spatial proximity between DNA regions; contact need not imply functional regulation.'],
['Spatial transcriptomics','空间转录组','把基因表达放回组织位置，连接细胞与邻居。','Places gene expression in tissue coordinates, connecting cells and neighbors.'],
['Pseudotime','伪时间','按状态推测排序，不是真实追踪同一个人或细胞的时间。','An inferred ordering of states, not measured time for the same person or cell.'],
['Counterfactual','反事实','同一对象接受另一种干预会怎样；无法同时观测两种现实。','What the same unit would do under a different intervention; both realities cannot be observed together.'],
['Batch effect','批次效应','实验日期、机器或操作造成的差异，可能被误当疾病差异。','Differences from date, instrument or procedure that can masquerade as disease effects.'],
['Pseudobulk','伪 bulk 汇总','按供体或条件汇总细胞，帮助保持正确统计样本单位。','Aggregate cells by donor or condition to preserve the appropriate statistical unit.'],
['Foundation model','基础模型','先在大数据上学习，再适配多个任务；不自动保证新任务可靠。','Pretrain on large data, then adapt to multiple tasks; reliability on new tasks is not automatic.'],
['OOD','分布外泛化','训练中没见过的供体、细胞、药物或时间，可能更难预测。','Unseen donors, cells, drugs or timepoints may be harder to predict.'],
['eQTL / GWAS','表达关联 / 全基因组关联','连接变异与表达或性状；关联仍需精细定位和实验。','Link variants to expression or traits; associations still require fine-mapping and experiments.'],
['iPSC / organoid','诱导干细胞 / 类器官','实验室中重建人源细胞或部分组织；不能完全替代患者。','Human-derived cells or partial tissues built in the lab; not complete substitutes for patients.'],
['WSI','全切片图像','高分辨率数字病理切片，通常拆成很多图像块处理。','A high-resolution pathology slide, typically processed as many image patches.'],
['SMILES / mmCIF','分子字符串 / 结构文件','SMILES 描述连接关系；mmCIF 记录三维结构与原子信息。','SMILES represents molecular connectivity; mmCIF records 3D structures and atoms.'],
['MCP / agent','工具接口 / 代理','MCP 连接工具；代理规划并调用工具。二者都不保证科学结论正确。','MCP connects tools; agents plan and call them. Neither guarantees scientific correctness.'],
['DUA','数据使用协议','规定谁能用数据、可用于什么、能否分享或发送到外部服务。','Defines who may use data, permitted purposes, sharing and external-service restrictions.']
];
